"""Freeze own-source geometry, surface observations and articulated-pose comparisons."""
import argparse,json,hashlib,shutil
from pathlib import Path
import numpy as np
from PIL import Image,ImageDraw
ROOT=Path(__file__).resolve().parents[3];BASE=ROOT/'level-editor/work/croisement02-refinement';sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest();pin=lambda p:dict(path=str(p),sha256=sha(p))
def main():
 p=argparse.ArgumentParser();p.add_argument('--output',type=Path,required=True);a=p.parse_args();a.output.mkdir(exist_ok=False);cards=[]
 for number,review_version,solid_version in [(1,1,1),(2,3,1),(3,2,1),(6,2,2)]:
  fitp=BASE/f'restart78-butterfly{number:02}-own-poses-v1/fit.json';fit=json.loads(fitp.read_text());review=BASE/f'restart86-butterfly{number:02}-import-review-v{review_version}';solid=BASE/f'restart93-butterfly{number:02}-solid-v{solid_version}';imported=json.loads((review/'report.json').read_text());model=BASE/f'restart84-butterfly{number:02}-fullpath-v{2 if number==1 else 1}'/f'butterfly{number:02}-fullpath.glb';assert sha(model)==imported['model_sha256']==json.loads((solid/'report.json').read_text())['model_sha256'];folder=a.output/f'butterfly{number:02}';folder.mkdir();scale=imported['views'][0]['ortho_scale'];frames=[]
  for first in range(0,99,25):
   sheet=Image.new('RGB',(1280,760),'#252525');draw=ImageDraw.Draw(sheet)
   for offset,row in enumerate(fit['rows'][first:first+25]):
    sourcep=Path(row['source']['source']);assert sha(sourcep)==row['source']['sha256'];arr=np.asarray(Image.open(sourcep).convert('RGBA'));yy,xx=np.nonzero(arr[:,:,3]>0);center=np.array([xx.mean()+.5,yy.mean()+.5]);gy,gx=np.mgrid[:128,:128];sx=np.floor((gx+.5-64)*scale/128+center[0]).astype(int);sy=np.floor((gy+.5-64)*scale/128+center[1]).astype(int);valid=(sx>=0)&(sy>=0)&(sx<arr.shape[1])&(sy<arr.shape[0]);pixels=np.zeros((128,128,4),np.uint8);pixels[valid]=arr[sy[valid],sx[valid]];source=Image.new('RGBA',(128,128),'#252525');source.alpha_composite(Image.fromarray(pixels));render=Image.open(review/f"anatomy/{row['phase']:03}.png").convert('RGBA').resize((128,128),Image.Resampling.NEAREST);dx,dy=np.array(row['parameters'][5:7])*128/scale;render=render.transform((128,128),Image.Transform.AFFINE,(1,0,-dx,0,1,-dy),resample=Image.Resampling.NEAREST);model_frame=Image.new('RGBA',(128,128),'#252525');model_frame.alpha_composite(render);x=offset%5*256;y=offset//5*152;sheet.paste(source.convert('RGB'),(x,y+20));sheet.paste(model_frame.convert('RGB'),(x+128,y+20));draw.text((x+3,y+3),f"{row['phase']:02} source | imported geometry",fill='white');frames.append(model_frame.convert('RGB'))
   sheet.save(folder/f'comparison-{first:02}.png')
  for source,name in [(review/'isolated-eight.png','textured-eight.png'),(solid/'solid-eight.png','solid-eight.png'),(review/'anatomy-motion.gif','articulation.gif')]:shutil.copyfile(source,folder/name)
  card=dict(asset_id=f'croisement02-butterfly{number:02}',model=pin(model),fit=pin(fitp),import_review=pin(review/'report.json'),solid_review=pin(solid/'report.json'),scope='Fixed body and rigid wings, own-source observed colors, and 99 articulated source poses only. Does not approve inferred map-relative flight depth/path or visibility integration.',source_pixels=fit['source_pixels'],missing_centers=fit['missing_pixels'],bright_missing_centers=fit['bright_missing'],extra_centers=fit['extra_pixels'],images=[pin(q) for q in sorted(folder.glob('*.png'))],canonical_writes=False);cards.append(card)
  html=f'<h1>Butterfly{number:02}: geometry and source colors</h1><p>{card["scope"]}</p><p>Original art camera is top-left in both eight-view sheets. Colors come from this butterfly’s 99 source frames; no generated fill. Physical body shape and surface ownership are inferred. {card["missing_centers"]} of {card["source_pixels"]} source-pixel centers remain outside the fitted shape ({card["bright_missing_centers"]} bright); tiny body and edge pixels remain uncertain.</p><h2>Exact imported shape and appearance</h2><img src="solid-eight.png"><img src="textured-eight.png"><h2>Articulation in a following camera</h2><p>This does not show map-relative flight or neighbors.</p><img src="articulation.gif"><h2>All 99 source poses at the same scale</h2><p>Left is source, right is imported geometry with the fitted registration restored. These are visual comparisons, not pixel-equality claims.</p>'+''.join(f'<img src="comparison-{i:02}.png">' for i in range(0,99,25));(folder/'index.html').write_text('<!doctype html><meta charset="utf-8"><style>body{font:16px sans-serif;background:#222;color:#ddd;margin:24px}p{max-width:1000px}img{max-width:100%;display:block;margin:16px 0}</style>'+html)
 (a.output/'handoff.json').write_text(json.dumps(dict(status='OWNER_COMPARISON_REVIEW_PENDING_NOT_USER_APPROVAL',cards=cards,scope='Four geometry/observed-surface/articulation cards; full flight depth and scene integration excluded.',synthesis_requested=False),indent=2)+'\n');(a.output/'index.html').write_text('<!doctype html><meta charset="utf-8"><h1>Four own-source butterfly geometry candidates</h1><p>Geometry, observed colors and articulated poses only; flight depth/path and scene integration are excluded. Owner comparison review pending.</p>'+''.join(f'<p><a href="butterfly{n:02}/index.html">Butterfly{n:02}</a></p>' for n in [1,2,3,6]));print(a.output/'handoff.json')
if __name__=='__main__':main()
